+      title={`Inputs: ${JSON.stringify(r.evidence || {})}; observation ${r.asof || "unknown"}`}>
+      <span>#{r.rank ?? "—"} {r.ticker}</span><span>{r.conviction.toFixed(1)} rank points</span></button>)}</div>
