+      {(body.availability || []).filter(r => r.reason).map((r, i) => <p key={`${r.ticker}-${i}`}>{r.ticker} · {r.reason}</p>)}</details>}
+    <button className="btn text-[10px]" onClick={() => load(false)} disabled={scanning}>Retry read</button>
+  </section>;
+}

