+ expect(checkedChartAction({kind:'open_chart',view:'skylit',ticker:'SPY',fact_ids:['f1']},answer)).toBeNull();
+ expect(checkedChartAction({kind:'open_chart',view:'heatseeker',ticker:'SPY',fact_ids:['missing']},answer)).toBeNull();
+});
