+  try {
+    const data = typeof raw === 'string' ? JSON.parse(raw) : raw;
+    if (!data || typeof data !== 'object') return { recovered: true, layout: createLayout() };
+    return { recovered: false, layout: { ...createLayout(), ...data, schema_version: SCHEMA_VERSION } };
+  } catch {
