+            {d.locked ? 'Unlock' : 'Lock'}
+          </button>
+          <button type="button" data-testid={'rail-hide-' + d.id} onClick={() => onToggleHide?.(d.id)}>
+            {d.visible === false ? 'Show' : 'Hide'}
+          </button>
+        </div>
+      ))}
+    </div>
+  );
+}

